@testset "Guarded crash interfaces" begin
    @test isdefined(JSimplex, :crash_basis)
    @test isdefined(JSimplex, :initialize_from_basis)
end

if isdefined(JSimplex, :crash_basis) && isdefined(JSimplex, :initialize_from_basis)

@testset "Crash produces an owned feasible structural diagonal basis" begin
        for T in (Float32, Float64, BigFloat, Rational{Int64}, Rational{BigInt}),
            method in (:pfi, :forrest_tomlin, :suhl_suhl, :bartels_golub),
            backend in (:native, :markowitz)
            p = LinearProblem(sparse(T[2 0; 0 3]), ones(T,2); row_lower=T[2,3])
            original = deepcopy(p)
            options = SolverOptions(T; verbose=false, basis_update=method,
                basis_refactorization=backend)
            policy = JSimplex.NumericalPolicy(T; crash=true)
            b = JSimplex.crash_basis(p,options,policy,()->false)
            @test Set(b.basic_indices) == Set([1,2])
            ws = JSimplex.initialize_from_basis(p,b,options; policy)
            @test ws.primal[1:2] ≈ ones(T,2)
            @test iszero(JSimplex.primal_infeasibility(ws))
            @test JSimplex._recomputed_basis_reliable(ws)
            @test ws.basis.basic_indices !== b.basic_indices
            @test ws.basis.states !== b.states
            @test p.A == original.A && p.objective == original.objective
            @test p.column_lower == original.column_lower && p.column_upper == original.column_upper
            @test p.row_lower == original.row_lower && p.row_upper == original.row_upper
        end
    end

@testset "Crash chooses legal objective-aware nonbasic states" begin
        for sense in (MIN_SENSE,MAX_SENSE)
            p = LinearProblem(spzeros(0,4),[-1.0,1.0,-2.0,3.0];
                column_lower=[0.0,-Inf,2.0,-Inf], column_upper=[4.0,5.0,2.0,Inf],
                objective_sense=sense)
            options = SolverOptions(verbose=false)
            policy = JSimplex.NumericalPolicy(Float64;crash=true)
            b = JSimplex.crash_basis(p,options,policy,()->false)
            @test isempty(b.basic_indices)
            @test b.states == [sense == MIN_SENSE ? JSimplex.AT_UPPER : JSimplex.AT_LOWER,
                JSimplex.AT_UPPER,JSimplex.AT_LOWER,JSimplex.FREE_NONBASIC]
            ws = JSimplex.initialize_from_basis(p,b,options;policy)
            @test ws.primal == [sense == MIN_SENSE ? 4.0 : 0.0,5.0,2.0,0.0]
        end
        p = LinearProblem(spzeros(2,0),Float64[];row_lower=[0.0,1.0])
        b = JSimplex.crash_basis(p,SolverOptions(verbose=false),
            JSimplex.NumericalPolicy(Float64;crash=true),()->false)
        @test b.basic_indices == [1,2]
    end

@testset "Crash guards dependent columns and zero columns" begin
        p = LinearProblem(sparse([1.0 1 0;1 1+1e-12 0]),ones(3);
            row_lower=[1.0,2.0],row_upper=[1.0,2.0])
        options = SolverOptions(verbose=false)
        policy = JSimplex.NumericalPolicy(Float64;crash=true)
        b = JSimplex.crash_basis(p,options,policy,()->false)
        @test !(1 in b.basic_indices && 2 in b.basic_indices)
        @test !(3 in b.basic_indices)
        ws = JSimplex.initialize_from_basis(p,b,options;policy)
        @test JSimplex._recomputed_basis_reliable(ws)
        slack = JSimplex.initialize_workspace(p,options)
        @test JSimplex.primal_infeasibility(ws) <= JSimplex.primal_infeasibility(slack)
        invalid = JSimplex.Basis([1,1],fill(JSimplex.BASIC,5))
        @test_throws ArgumentError JSimplex.initialize_from_basis(p,invalid,options;policy)
    end

@testset "Crash consumes the existing clock and completed-step budget" begin
        p = LinearProblem(spdiagm(0=>[2.0,3.0]),ones(2);row_lower=[2.0,3.0])
        policy = JSimplex.NumericalPolicy(Float64;simplex_strategy=:adaptive,crash=true)
        for algorithm in (:primal,:dual)
            options = SolverOptions(verbose=false,presolve=false,algorithm=algorithm,iteration_limit=1)
            d = JSimplex.SimplexDiagnostics(kernel_timing=true)
            r = JSimplex._solve_diagnosed(p,d;options,numerical_policy=policy)
            @test r.status == ITERATION_LIMIT
            @test r.statistics.iterations == 1
            @test JSimplex.event_count(d,:crash_pivot) == 1
            progress = JSimplex.SimplexProgressContext(p;start_ns=time_ns()-UInt64(2_000_000_000),
                numerical_policy=policy)
            timed = SolverOptions(verbose=false,presolve=false,algorithm=algorithm,time_limit=0.1)
            run = algorithm == :primal ? JSimplex._solve_continuous_primal(p,timed;progress) :
                JSimplex._solve_continuous_dual(p,timed;progress)
            @test run.status == TIME_LIMIT
            @test run.iterations == 0
        end
        calls = Ref(0)
        b = JSimplex.crash_basis(p,SolverOptions(verbose=false),policy,()->(calls[]+=1)>2)
        @test b.basic_indices == [3,4]
        failure = SingularException(42)
        try
            JSimplex.crash_basis(p,SolverOptions(verbose=false),policy,()->throw(failure))
            @test false
        catch exception
            @test exception === failure
        end
    end
end

@testset "Crash respects fixed, upper-only and free variables with rows" begin
    p = LinearProblem(spdiagm(0=>ones(3)),[0.0,-1.0,1.0];
        column_lower=[2.0,-Inf,-Inf],column_upper=[2.0,3.0,Inf],
        row_lower=[2.0,3.0,1.0],row_upper=[2.0,3.0,1.0])
    for algorithm in (:primal,:dual)
        options = SolverOptions(;verbose=false,algorithm)
        policy = JSimplex.NumericalPolicy(Float64;crash=true)
        basis = JSimplex.crash_basis(p,options,policy,()->false)
        ws = JSimplex.initialize_from_basis(p,basis,options;policy)
        @test ws.primal[1:3] == [2.0,3.0,1.0]
        @test basis.states[1:3] == [JSimplex.AT_LOWER,JSimplex.AT_UPPER,JSimplex.BASIC]
        @test iszero(JSimplex.primal_infeasibility(ws))
    end
end

@testset "Crash rejects objective-aware states with worse primal violation" begin
    p = LinearProblem(sparse([1.0 1.0]),[-1.0,-1.0];column_upper=ones(2),row_upper=[0.0])
    d = JSimplex.SimplexDiagnostics()
    policy = JSimplex.NumericalPolicy(Float64;crash=true)
    progress = JSimplex.SimplexProgressContext(p;diagnostics=d,numerical_policy=policy)
    initial = JSimplex.initialize_workspace(p,SolverOptions(verbose=false);progress)
    ws,expired = JSimplex._crash_workspace(initial,()->false)
    @test ws === initial
    @test !expired
    @test ws.primal == zeros(3)
    @test JSimplex.event_count(d,:crash_fallback) == 1
    @test ws.iterations == 0
end

@testset "Crash interruption after final factorization uses no fresh budget" begin
    p = LinearProblem(spdiagm(0=>[2.0,3.0]),ones(2);row_lower=[2.0,3.0])
    done = Ref(false)
    d = JSimplex.SimplexDiagnostics(;observer=(reason,ws)->begin
        reason == :refactor_other && (done[]=true)
    end)
    policy = JSimplex.NumericalPolicy(Float64;crash=true)
    progress = JSimplex.SimplexProgressContext(p;diagnostics=d,numerical_policy=policy)
    initial = JSimplex.initialize_workspace(p,SolverOptions(verbose=false);progress)
    ws,expired = JSimplex._crash_workspace(initial,()->done[])
    @test expired
    @test ws === initial
    @test ws.iterations == 2
    @test ws.refactorizations >= 2
    @test ws.basis.basic_indices == [3,4]
    @test JSimplex.event_count(d,:crash_accepted) == 0
end

@testset "Crash refuses a relatively tiny pivot even for a feasible structural basis" begin
    delta = 1e-14
    p = LinearProblem(sparse([1.0 1.0;1.0 1.0+delta]),ones(2);
        row_lower=[2.0,2.0+delta],row_upper=[2.0,2.0+delta])
    options = SolverOptions(;verbose=false,algorithm=:dual,primal_tolerance=1e-16)
    policy = JSimplex.NumericalPolicy(Float64;crash=true)
    d = JSimplex.SimplexDiagnostics()
    progress = JSimplex.SimplexProgressContext(p;diagnostics=d,numerical_policy=policy)
    initial = JSimplex.initialize_workspace(p,options;progress)
    ws,expired = JSimplex._crash_workspace(initial,()->false)
    @test !expired
    @test JSimplex.event_count(d,:crash_pivot) == 1
    @test !(1 in ws.basis.basic_indices && 2 in ws.basis.basic_indices)
    @test JSimplex._recomputed_basis_reliable(ws)
end

@testset "Crash fill rejection retains verified slack state" begin
    p = LinearProblem(sparse([1.0 1;1 2]),ones(2);row_lower=[1.0,2.0])
    d = JSimplex.SimplexDiagnostics()
    policy = JSimplex.NumericalPolicy(Float64;crash=true)
    progress = JSimplex.SimplexProgressContext(p;diagnostics=d,numerical_policy=policy)
    initial = JSimplex.initialize_workspace(p,SolverOptions(verbose=false);progress)
    baseline = copy(initial.primal)
    ws,expired = JSimplex._crash_workspace(initial,()->false;fill_limit=1)
    @test !expired
    @test ws.basis.basic_indices == [3,4]
    @test ws.primal == baseline
    @test JSimplex.event_count(d,:crash_rejected_fill) > 0
    @test JSimplex._recomputed_basis_reliable(ws)
    @test_throws ArgumentError JSimplex._crash_workspace(initial,()->false;fill_limit=Inf)
end

@testset "Crash interruption retains completed work and latches the stop" begin
    for algorithm in (:primal,:dual)
        p = LinearProblem(spdiagm(0=>[2.0,3.0]),ones(2);row_lower=[2.0,3.0])
        policy = JSimplex.NumericalPolicy(Float64;crash=true)
        interrupted = Ref(false)
        d = JSimplex.SimplexDiagnostics(;observer=(reason,ws)->begin
            reason == :crash_pivot && (interrupted[]=true)
        end)
        progress = JSimplex.SimplexProgressContext(p;diagnostics=d,numerical_policy=policy)
        options = SolverOptions(;verbose=false,presolve=false,algorithm)
        stop = ()->begin
            value = interrupted[]
            interrupted[] = false
            value
        end
        run = algorithm == :primal ? JSimplex._solve_continuous_primal(p,options;progress,stop_requested=stop) :
            JSimplex._solve_continuous_dual(p,options;progress,stop_requested=stop)
        @test run.status == TIME_LIMIT
        @test run.iterations == 1
        @test JSimplex.event_count(d,:crash_fallback) == 1
        @test JSimplex.event_count(d,:phase_one) == 0
        @test JSimplex.event_count(d,:phase_dual) == 0
    end
end

@testset "Crash observer failures retain their cause" begin
    p = LinearProblem(sparse(reshape([2.0],1,1)),[1.0];row_lower=[2.0])
    for event in (:phase_crash,:crash_pivot,:crash_accepted)
        failure = SingularException(42)
        d = JSimplex.SimplexDiagnostics(;observer=(reason,ws)->reason == event ? throw(failure) : nothing)
        policy = JSimplex.NumericalPolicy(Float64;crash=true)
        progress = JSimplex.SimplexProgressContext(p;diagnostics=d,numerical_policy=policy)
        try
            JSimplex._solve_continuous_primal(p,SolverOptions(verbose=false);progress)
            @test false
        catch exception
            @test exception isa JSimplex.DiagnosticObserverFailure
            @test exception.cause === failure
        end
    end
end

@testset "Crash skips phase one only after measured feasibility" begin
    p = LinearProblem(spdiagm(0=>[2.0,3.0]),ones(2);row_lower=[2.0,3.0])
    for algorithm in (:primal,:dual), crash in (false,true)
        d = JSimplex.SimplexDiagnostics(kernel_timing=true)
        policy = JSimplex.NumericalPolicy(Float64;simplex_strategy=:adaptive,crash)
        options = SolverOptions(;verbose=false,presolve=false,algorithm,simplex_strategy=:adaptive)
        result = JSimplex._solve_diagnosed(p,d;options,numerical_policy=policy)
        @test result.status == OPTIMAL
        @test result.objective_value ≈ 2.0
        @test result.primal ≈ ones(2)
        @test JSimplex.event_count(d,:crash_pivot) == (crash ? 2 : 0)
        @test d.kernel_calls[:crash] == (crash ? 1 : 0)
        if algorithm == :primal
            @test JSimplex.event_count(d,:phase_one) == (crash ? 0 : 1)
        end
    end
end

@testset "Imported start rejects singular bases and illegal nonbasic bounds" begin
    p = LinearProblem(sparse([1.0 1;1 1]),ones(2);row_lower=ones(2))
    options = SolverOptions(verbose=false)
    b = JSimplex.Basis([1,2],[JSimplex.BASIC,JSimplex.BASIC,JSimplex.AT_LOWER,JSimplex.AT_LOWER])
    @test_throws Union{SingularException,ZeroPivotException,JSimplex._UnreliableBasisSolve} JSimplex.initialize_from_basis(p,b,options)
    b = JSimplex.Basis([3,4],[JSimplex.FREE_NONBASIC,JSimplex.AT_LOWER,JSimplex.BASIC,JSimplex.BASIC])
    @test_throws ArgumentError JSimplex.initialize_from_basis(p,b,options)
    b = JSimplex.Basis([3,4],[JSimplex.AT_UPPER,JSimplex.AT_LOWER,JSimplex.BASIC,JSimplex.BASIC])
    @test_throws ArgumentError JSimplex.initialize_from_basis(p,b,options)
end

@testset "Crash preserves stored BigFloat precision below ambient precision" begin
    setprecision(BigFloat,256) do
        coefficient = 1+BigFloat(2)^-100
        p = LinearProblem(sparse(reshape([coefficient],1,1)),BigFloat[1];row_lower=[coefficient])
        policy = JSimplex.NumericalPolicy(BigFloat;crash=true)
        options = SolverOptions(BigFloat;verbose=false)
        setprecision(BigFloat,64) do
            b = JSimplex.crash_basis(p,options,policy,()->false)
            ws = JSimplex.initialize_from_basis(p,b,options;policy)
            @test ws.primal[1] == 1
            @test precision(ws.primal[1]) >= 256
            @test precision(BigFloat) == 64
            @test p.A[1,1] == coefficient
        end
    end
end

@testset "Crash arithmetic overflow falls back without changing exact input" begin
    T = Rational{Int64}
    p = LinearProblem(sparse(reshape(T[1,1],1,2)),T[-1,-1];
        column_upper=T[typemax(Int64),typemax(Int64)])
    original = deepcopy(p)
    policy = JSimplex.NumericalPolicy(T;crash=true)
    d = JSimplex.SimplexDiagnostics()
    progress = JSimplex.SimplexProgressContext(p;numerical_policy=policy,diagnostics=d)
    initial = JSimplex.initialize_workspace(p,SolverOptions(T;verbose=false);progress)
    ws,expired = JSimplex._crash_workspace(initial,()->false)
    @test ws === initial
    @test !expired
    @test JSimplex.event_count(d,:crash_fallback) == 1
    @test p.A == original.A && p.column_upper == original.column_upper
    @test eltype(ws.primal) == T
end

@testset "Crash drivers create the slack fallback at stored precision" begin
    setprecision(BigFloat,256) do
        p = LinearProblem(sparse(reshape(BigFloat[1+BigFloat(2)^-100],1,1)),BigFloat[1];
            column_lower=BigFloat[1],row_lower=BigFloat[1])
        policy = JSimplex.NumericalPolicy(BigFloat;crash=true)
        for algorithm in (:primal,:dual)
            first_slack = Ref{Union{Nothing,BigFloat}}(nothing)
            d = JSimplex.SimplexDiagnostics(;observer=(reason,ws)->begin
                if reason == :refactor_initial && isnothing(first_slack[])
                    first_slack[] = copy(ws.primal[2])
                end
            end)
            progress = JSimplex.SimplexProgressContext(p;numerical_policy=policy,diagnostics=d)
            options = SolverOptions(BigFloat;verbose=false,algorithm)
            setprecision(BigFloat,64) do
                stop = ()->!isnothing(first_slack[])
                run = algorithm == :primal ? JSimplex._solve_continuous_primal(p,options;progress,stop_requested=stop) :
                    JSimplex._solve_continuous_dual(p,options;progress,stop_requested=stop)
                @test run.status == TIME_LIMIT
                @test first_slack[] == p.A[1,1]
                @test precision(first_slack[]) >= 256
                @test precision(BigFloat) == 64
            end
        end
    end
end

@testset "Legacy phase construction does not sum overflowing original violations" begin
    T = Rational{Int64}
    p = LinearProblem(spdiagm(0=>ones(T,2)),zeros(T,2);
        row_lower=fill(T(typemax(Int64)),2))
    options = SolverOptions(T;verbose=false,algorithm=:primal)
    ws,count,initial = JSimplex._primal_phase_one(p,options,
        JSimplex.SimplexProgressContext(p),()->false)
    @test count == 2
    @test iszero(JSimplex.primal_infeasibility(ws))
end

@testset "Crash falls back when the initial exact violation sum overflows" begin
    T = Rational{Int64}
    p = LinearProblem(spdiagm(0=>ones(T,2)),zeros(T,2);
        row_lower=fill(T(typemax(Int64)),2))
    policy = JSimplex.NumericalPolicy(T;crash=true)
    d = JSimplex.SimplexDiagnostics()
    progress = JSimplex.SimplexProgressContext(p;numerical_policy=policy,diagnostics=d)
    options = SolverOptions(T;verbose=false,algorithm=:primal)
    initial = JSimplex.initialize_workspace(p,options;progress)
    ws,expired = JSimplex._crash_workspace(initial,()->false)
    @test ws === initial && !expired
    @test ws.iterations == 0
    @test JSimplex.event_count(d,:crash_fallback) == 1
    phase,count,_ = JSimplex._primal_phase_one(p,options,progress,()->false;initial=ws)
    @test count == 2
    @test iszero(JSimplex.primal_infeasibility(phase))
    limited = SolverOptions(T;verbose=false,algorithm=:primal,iteration_limit=0)
    run = JSimplex._solve_continuous_primal(p,limited;progress)
    @test run.status == ITERATION_LIMIT && run.iterations == 0
end

@testset "Phase one checks cancellation after entry recomputation" begin
    p=LinearProblem(sparse([1.0;;]),[1.0];row_lower=[0.0])
    policy=JSimplex.NumericalPolicy(Float64;phase_one=true)
    ws=JSimplex.initialize_workspace(p,SolverOptions(verbose=false);
        progress=JSimplex.SimplexProgressContext(p;numerical_policy=policy))
    checks=Ref(0)
    result=JSimplex.run_phase_one!(ws,JSimplex.SimplexRunBudget(ws),policy,()->(checks[]+=1;checks[]>1))
    @test result.status==TIME_LIMIT
    @test ws.iterations==0
end

@testset "Phase one solves from a violated structural basis" begin
    for T in (Float64,Rational{BigInt}),infeasible in (false,true)
        p=LinearProblem(sparse(T[2 1;1 3]),T[1,2];column_lower=T[2,0],
            row_lower=T[2,0],row_upper=infeasible ? [Bound(T(2)),Bound{T}(nothing)] : fill(Bound{T}(nothing),2))
        policy=JSimplex.NumericalPolicy(T;simplex_strategy=:adaptive,phase_one=true)
        options=SolverOptions(T;algorithm=:primal,verbose=false)
        basis=JSimplex.Basis([1,4],[JSimplex.BASIC,JSimplex.AT_LOWER,JSimplex.AT_LOWER,JSimplex.BASIC])
        ws=JSimplex.initialize_from_basis(p,basis,options;policy)
        budget=JSimplex.SimplexRunBudget(ws)
        phase=JSimplex.run_phase_one!(ws,budget,policy,()->false)
        @test phase.status==(infeasible ? INFEASIBLE : OPTIMAL)
        @test length(ws.basis.states)==4
        if !infeasible
            result=JSimplex.run_from_basis!(ws,budget,policy,()->false)
            @test result.status==OPTIMAL
            @test result.objective_value==T(2)
        end
    end
end

@testset "Partially feasible crash basis is extended without slack restart" begin
    for T in (Float64,Rational{BigInt})
        p=LinearProblem(sparse(reshape(T[1,1],2,1)),T[1];row_lower=T[1,2],row_upper=T[1,2])
        policy=JSimplex.NumericalPolicy(T;simplex_strategy=:adaptive,crash=true,phase_one=true)
        d=JSimplex.SimplexDiagnostics()
        options=SolverOptions(T;algorithm=:primal,verbose=false)
        ws=JSimplex.initialize_workspace(p,options;
            progress=JSimplex.SimplexProgressContext(p;numerical_policy=policy,diagnostics=d))
        crash,expired=JSimplex._crash_workspace(ws,()->false)
        @test !expired
        @test JSimplex.event_count(d,:crash_accepted)==1
        @test !JSimplex._start_primal_feasible(crash)
        phase,map=JSimplex._phase_one_workspace(crash,policy,()->false)
        @test length(map.artificial_columns)==1
        @test JSimplex._start_primal_feasible(phase)
        result=JSimplex.run_phase_one!(crash,JSimplex.SimplexRunBudget(crash),policy,()->false)
        # Floating interval arithmetic cannot prove an exactly zero A' y
        # coefficient on an unbounded variable. Keep that proof inconclusive.
        @test result.status==(T <: Rational ? INFEASIBLE : NUMERICAL_ERROR)
        T <: AbstractFloat && @test occursin("certificate is inconclusive",result.message)
    end
end
